#!/bin/bash
# ============================================================
#  Talos Agent installer (Linux / CentOS)
#
#    scripts-linux/install.sh --server HOST:PORT --token TOKEN [--id ID]
#    scripts-linux/install.sh            (reuse conf/agent.yml if present)
#    scripts-linux/install.sh --server ... --silent --no-cron
#
#  Steps:
#    1. locate java (17+)
#    2. write conf/agent.yml (an existing one is backed up before a
#       rewrite and reused as-is when no explicit flags are given)
#    3. register a crontab keepalive that checks every 5 minutes
#    4. start the agent once
#
#  Keep LF line endings.  Fix with:  sed -i 's/\r$//' scripts-linux/*.sh
# ============================================================
set -u

APP_HOME="$(cd "$(dirname "$0")/.." && pwd)"
cd "$APP_HOME" || exit 1

CRON_TAG="# talos-agent keepalive"

usage() {
  cat <<'USAGE'
Usage: scripts-linux/install.sh --server HOST:PORT [--token TOKEN] [--id ID]
                                [--http-port PORT] [--workspace DIR]
                                [--sign-secret SECRET] [--no-cron] [--silent]

  --server       Talos server gRPC address, e.g. talos.internal:9443
  --token        one-time enrollment token from the console
  --id           client id, defaults to this machine's hostname
  --http-port    console HTTP port used for upgrade downloads (default 8080)
  --workspace    where node tasks check out code (default <install>/workspace)
  --sign-secret  must equal the server's talos.security.task-sign-secret;
                 leave empty to skip task-signature verification
  --no-cron      do not register the crontab keepalive
  --silent       never prompt (for unattended deployment)

  With no flags an existing conf/agent.yml is reused as-is.
USAGE
}

ADDR=""
PORT=""
HTTPPORT=""
TOKEN=""
CID=""
WS=""
SIGN=""
EXPLICIT=0
SILENT=0
NO_CRON=0

while [ $# -gt 0 ]; do
  case "$1" in
    --server)
      V="${2:-}"; shift 2
      ADDR="${V%%:*}"
      PORT="${V##*:}"
      [ "$PORT" = "$ADDR" ] && PORT=""
      EXPLICIT=1 ;;
    --http-port)   HTTPPORT="${2:-}"; shift 2 ;;
    --token)       TOKEN="${2:-}";    EXPLICIT=1; shift 2 ;;
    --id)          CID="${2:-}";      EXPLICIT=1; shift 2 ;;
    --workspace)   WS="${2:-}";       EXPLICIT=1; shift 2 ;;
    --sign-secret) SIGN="${2:-}";     EXPLICIT=1; shift 2 ;;
    --no-cron)     NO_CRON=1; shift ;;
    --silent)      SILENT=1; shift ;;
    -h|--help)     usage; exit 0 ;;
    *) echo "[Talos] ERROR: unknown argument: $1"; usage; exit 1 ;;
  esac
done

[ -z "$ADDR" ]     && ADDR="localhost"
[ -z "$PORT" ]     && PORT="9443"
[ -z "$HTTPPORT" ] && HTTPPORT="8080"
[ -z "$WS" ]       && WS="$APP_HOME/workspace"
[ -z "$CID" ]      && CID="$(hostname 2>/dev/null || echo talos-agent)"

# Explicit flags mean "reconfigure". Otherwise an existing config wins.
REUSE=0
if [ "$EXPLICIT" -eq 0 ] && [ -f conf/agent.yml ]; then
  REUSE=1
fi

echo "[Talos] ============================================"
echo "[Talos]  Talos Agent installer (Linux)"
echo "[Talos]  home   : $APP_HOME"
echo "[Talos]  server : $ADDR:$PORT"
echo "[Talos]  client : $CID"
echo "[Talos] ============================================"

# ---------- 1/4 java ----------
JAVA_BIN="$(command -v java 2>/dev/null || true)"
if [ -z "$JAVA_BIN" ]; then
  echo "[Talos] ERROR: java not found on PATH. Install a JRE 17+ and retry:"
  echo "[Talos]        yum install -y java-17-openjdk-headless"
  exit 1
fi
JVER="$("$JAVA_BIN" -version 2>&1 | head -n1 | sed -n 's/.*version "\([0-9][0-9]*\).*/\1/p')"
[ -z "$JVER" ] && JVER=0
if [ "$JVER" -lt 17 ]; then
  echo "[Talos] ERROR: JRE 17+ required, found: $("$JAVA_BIN" -version 2>&1 | head -n1)"
  exit 1
fi
echo "[Talos] 1/4 java OK: $("$JAVA_BIN" -version 2>&1 | head -n1)"

if [ ! -f talos-agent.jar ]; then
  echo "[Talos] ERROR: talos-agent.jar not found in $APP_HOME"
  echo "[Talos]        Extract the whole package, keep talos-agent.jar,"
  echo "[Talos]        conf/ and scripts-linux/ together."
  exit 1
fi

# ---------- 2/4 conf/agent.yml ----------
mkdir -p logs run
if [ "$REUSE" -eq 1 ]; then
  echo "[Talos] 2/4 conf/agent.yml exists - keeping it untouched."
  echo "[Talos]     (pass --server/--token/--id to reconfigure,"
  echo "[Talos]      or delete the file to run a first-time setup)"
else
  echo "[Talos] 2/4 writing conf/agent.yml ..."
  mkdir -p conf
  if [ -f conf/agent.yml ]; then
    cp -f conf/agent.yml conf/agent.yml.bak
    echo "[Talos]     previous config backed up to conf/agent.yml.bak"
  fi

  cat > conf/agent.yml <<YAML
# Talos Agent client config - generated by scripts-linux/install.sh
# Field reference: the client integration guide on the console.
# Edit this file and restart the agent to apply changes.
#
# server.addr must be an address THIS machine can reach the server on.
# client.signSecret must equal the server's talos.security.task-sign-secret
# when signature verification is enabled there.

server:
  addr: $ADDR
  # gRPC port for the reverse long connection
  port: $PORT
  # console HTTP port, used to download upgrade packages
  httpPort: $HTTPPORT

client:
  id: $CID
  # one-time enrollment token issued in the console
  token: "$TOKEN"
  # where node tasks check out code and write artifacts
  workspace: '$WS'
  heartbeatSeconds: 10
  signSecret: "$SIGN"
  # set to false to refuse remote silent upgrades on this machine
  allowUpgrade: true

# Coding Agent backends available on this machine.
# The console can override backend/model per clientId.
agents:
  - backend: claude
    enabled: true
    model: claude-opus-4
    cmd: claude
    args: []
  - backend: cursor
    enabled: true
    model: cursor-pro
    cmd: cursor
    args: []
  - backend: codex
    enabled: false
    model: codex-1
    cmd: codex
    args: []
  - backend: codebuddy
    enabled: true
    model: cb-internal
    cmd: codebuddy
    args: []

log:
  dir: logs
YAML
  chmod 600 conf/agent.yml
  echo "[Talos]     conf/agent.yml written"
fi

# ---------- 3/4 crontab keepalive ----------
if [ "$NO_CRON" -eq 1 ]; then
  echo "[Talos] 3/4 --no-cron given, keepalive not registered."
elif ! command -v crontab >/dev/null 2>&1; then
  echo "[Talos] 3/4 WARNING: crontab not available on this host."
  echo "[Talos]     The agent will NOT restart by itself after a crash."
elif ! command -v crond >/dev/null 2>&1 && ! systemctl is-active crond >/dev/null 2>&1; then
  echo "[Talos] 3/4 WARNING: crond does not look active - start it first:"
  echo "[Talos]     systemctl enable --now crond"
else
  echo "[Talos] 3/4 registering the crontab keepalive (every 5 minutes) ..."
  CRON_CMD="$APP_HOME/scripts-linux/run-agent.sh"
  CRON_LINE="*/5 * * * * $CRON_CMD >> $APP_HOME/logs/cron.log 2>&1"
  TMP="$(mktemp)"
  # drop any previous entry (identified by its tag) before adding the new one
  crontab -l 2>/dev/null | grep -v -F "$CRON_TAG" | grep -v -F "scripts-linux/run-agent.sh" > "$TMP" || true
  echo "$CRON_TAG" >> "$TMP"
  echo "$CRON_LINE" >> "$TMP"
  if crontab "$TMP" 2>/dev/null; then
    echo "[Talos]     registered for user $(id -un):"
    echo "[Talos]       $CRON_LINE"
  else
    echo "[Talos]     WARNING: failed to install the crontab entry."
  fi
  rm -f "$TMP"
fi

# ---------- 4/4 start ----------
echo "[Talos] 4/4 starting the agent ..."
bash "$APP_HOME/scripts-linux/start.sh"
RC=$?

echo "[Talos] ============================================"
echo "[Talos]  Installed."
echo "[Talos]    config  : $APP_HOME/conf/agent.yml"
echo "[Talos]    log     : $APP_HOME/logs/agent.log"
echo "[Talos]    status  : scripts-linux/status.sh"
echo "[Talos]    stop    : scripts-linux/stop.sh"
echo "[Talos]    upgrade : scripts-linux/upgrade.sh"
echo "[Talos]    console : watch it online under \"Clients\""
echo "[Talos]  Uninstall: scripts-linux/uninstall.sh"
echo "[Talos] ============================================"
exit $RC
